import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

softmax_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void softmax_kernel(float* input, float* output, int num_rows, int row_size) {
    extern __shared__ float shared_mem[];

    int row = blockIdx.x;
    int tid = threadIdx.x;
    int stride = blockDim.x;

    float* row_ptr = input + row * row_size;
    float* out_ptr = output + row * row_size;

    // Find max value in row for numerical stability
    float max_val = -INFINITY;
    for (int i = tid; i < row_size; i += stride) {
        max_val = max(max_val, row_ptr[i]);
    }

    shared_mem[tid] = max_val;
    __syncthreads();

    // Parallel reduction for max value
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] = max(shared_mem[tid], shared_mem[tid + s]);
        }
        __syncthreads();
    }

    float row_max = shared_mem[0];
    __syncthreads();

    // Compute exponentials and sum
    float exp_sum = 0.0f;
    for (int i = tid; i < row_size; i += stride) {
        float val = expf(row_ptr[i] - row_max);
        out_ptr[i] = val;
        exp_sum += val;
    }

    shared_mem[tid] = exp_sum;
    __syncthreads();

    // Parallel reduction for sum
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] += shared_mem[tid + s];
        }
        __syncthreads();
    }

    // Normalize with sum
    float inv_sum = 1.0f / shared_mem[0];
    for (int i = tid; i < row_size; i += stride) {
        out_ptr[i] *= inv_sum;
    }
}

torch::Tensor softmax_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int num_rows = input.size(0);
    int row_size = input.size(1);

    const int block_size = 256;
    dim3 grid(num_rows);
    dim3 block(block_size);

    softmax_kernel<<<grid, block, block_size * sizeof(float)>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_rows,
        row_size
    );

    return output;
}
"""

softmax_cpp_source = "torch::Tensor softmax_cuda(torch::Tensor input);"

softmax_ext = load_inline(
    name='softmax_ext',
    cpp_sources=softmax_cpp_source,
    cuda_sources=softmax_cuda_source,
    functions=['softmax_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.softmax_op = softmax_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.softmax_op.softmax_cuda(x)
